// API Endpoints Configuration
const API_BASE_URL = 'http://localhost:3189';

// Studio Reels API Endpoints
const STUDIO_REELS_API = `${API_BASE_URL}/api/studio/reels`;

// Studio Authentication API Endpoints
const STUDIO_AUTH_API = `${API_BASE_URL}/Studio`;

export const API_ENDPOINTS = {
  // Base URLs
  BASE: API_BASE_URL,
  STUDIO_REELS: STUDIO_REELS_API,
  STUDIO_AUTH: STUDIO_AUTH_API,

  // Authentication Endpoints
  AUTH: {
    SELLER: {
      LOGIN: `${STUDIO_AUTH_API}/seller/login`,
      LOGIN_WITH_PASSWORD: `${STUDIO_AUTH_API}/seller/login-with-password`,
      SET_PASSWORD: `${STUDIO_AUTH_API}/seller/set-password`,
      CHECK_DETAILS: `${STUDIO_AUTH_API}/seller/check-details`,
      REGISTER_FOR_REELS: `${STUDIO_AUTH_API}/seller/register-for-reels`,
      CHECK_EMAIL: `${STUDIO_AUTH_API}/seller/check-email`,
      FORGOT_PASSWORD: `${STUDIO_AUTH_API}/seller/forgot-password`,
      RESET_PASSWORD: `${STUDIO_AUTH_API}/seller/reset-password`
    },
    INFLUENCER: {
      APPLY: `${STUDIO_AUTH_API}/influencer/apply`,
      LOGIN: `${STUDIO_AUTH_API}/influencer/login`,
      APPLY_FOR_REELS: `${STUDIO_AUTH_API}/influencer/apply-for-reels`,
      APPLICATIONS: `${STUDIO_AUTH_API}/influencer/applications`,
      APPROVE: (id) => `${STUDIO_AUTH_API}/influencer/${id}/approve`,
      REJECT: (id) => `${STUDIO_AUTH_API}/influencer/${id}/reject`,
      FORGOT_PASSWORD: `${STUDIO_AUTH_API}/influencer/forgot-password`,
      RESET_PASSWORD: `${STUDIO_AUTH_API}/influencer/reset-password`
    }
  },

  // Reels Endpoints
  REELS: {
    // Profile
    PROFILE: {
      UPLOAD_IMAGE: `${STUDIO_REELS_API}/profile/image`,
      UPDATE_IMAGE_PATH: `${STUDIO_REELS_API}/profile/image`
    },

    // Upload
    UPLOAD: {
      INFLUENCER: `${STUDIO_REELS_API}/influencer/upload`,
      SELLER: `${STUDIO_REELS_API}/seller/upload`
    },

    // Get Reels
    GET: {
      INFLUENCER_MY_REELS: `${STUDIO_REELS_API}/influencer/my-reels`,
      SELLER_REELS: (vendorId) => `${STUDIO_REELS_API}/seller/${vendorId}/reels`,
      SELLER_DASHBOARD_STATS: (vendorId) => `${STUDIO_REELS_API}/seller/${vendorId}/dashboard-stats`,
      SELLER_RECENT_REELS: (vendorId, limit = 5) => `${STUDIO_REELS_API}/seller/${vendorId}/recent-reels?limit=${limit}`,
      REEL_BY_ID: (id) => `${STUDIO_REELS_API}/${id}`
    },

    // Categories, Sellers, Brands
    CATEGORIES: `${STUDIO_REELS_API}/categories`,
    SELLERS: `${STUDIO_REELS_API}/sellers`,
    SELLER_PRODUCTS: (vendorId) => `${STUDIO_REELS_API}/sellers/${vendorId}/products`,
    BRANDS: `${STUDIO_REELS_API}/brands`,
    BRAND_PRODUCTS: (brandId) => `${STUDIO_REELS_API}/brands/${brandId}/products`,
    ALL_PRODUCTS: `${STUDIO_REELS_API}/products/all`,

    // Related Products
    RELATED_PRODUCTS: `${STUDIO_REELS_API}/related-products`,
    PRODUCT_NAMES: `${STUDIO_REELS_API}/product-names`,
    ALL_PRODUCT_NAMES: `${STUDIO_REELS_API}/all-product-names`,

    // Edit/Delete Reels
    EDIT_REEL: (id) => `${STUDIO_REELS_API}/${id}`,
    DELETE_REEL: (id) => `${STUDIO_REELS_API}/${id}`
  }
};

export default API_ENDPOINTS;
